  30   return useMutation({
  31     mutationFn: async (credentials: LoginCredentials) => {
  32       const result = await signIn('credentials', {
  33         email: credentials.email,
  34         password: credentials.password,
  35         redirect: false,
  36       });
  37       
  38       if (!result?.ok) {
  39         throw new Error(result?.error || 'Login failed');
  40       }
  41       
  42       return result;
  43     },
  44     onSuccess: async () => {
  45       await update();
  46       queryClient.invalidateQueries({ queryKey: userKeys.all });
  47       router.push('/builder');
  48       toast({ title: "Welcome back!" });
  49     },
  50     onError: (error) => handleErrorUtility(error, "Login Failed")
  51   });
  52 }
