 170 export function useSendPasswordReset() {
 171   const { session } = useAuth();
 172   const { toast } = useToast();
 173   return useMutation({
 174     mutationFn: async (userId: string) => {
 175       if (!session) throw new Error("Admin not authenticated.");
 176       // Get token from NextAuth session
 177       const response = await fetch('/api/auth/session');
 178       const data = await response.json();
 179       const token = data?.user?.id || '';
 180       return sendPasswordResetEmailApi(userId, token);
 181     },
 182     onSuccess: (data: any) => {
 183       toast({
 184         title: "Success",
